// Geschiedenissen (nt-3). Zie docs/BIJBELREIS.md, "De 150 geschiedenissen".
// Nummers 118–133: van de intocht in Jeruzalem tot de hemelvaart. Reisstappen staan in inhoud/nt-jezus-3.js (boek "jezus-3").
// Citaten uit de Statenvertaling; elke verwijzing en elk citaat staat in scripts/bijbel-controle/nt-3.txt.
BR.geschiedenissen = BR.geschiedenissen || [];
BR.kernwoorden = BR.kernwoorden || {};
(function () {
  const TL = [30, 33], TIJD = "ca. 30 of 33 n.Chr.";
  const NOOT = "Reconstructie. De Bijbel noemt geen jaartal. Lukas 3:1 noemt het vijftiende jaar van keizer Tiberius (volgens de gangbare berekening ca. 28/29 n.Chr.) en Pontius Pilatus was stadhouder van ca. 26 tot 36 n.Chr. (buiten-Bijbelse bronnen). Daarom wordt de kruisiging meestal op 30 of 33 n.Chr. gesteld; andere dateringen bestaan ook.";
  const S = (deel, i) => `jezus-3:${deel}:${i}`;

  BR.geschiedenissen.push(
{ nr: 118, t: "De intocht in Jeruzalem", ref: "Mattheüs 21:1–11", sectie: "pasen", stappen: [S("nt-lijdensweek", 0)], vorm: "route",
  uitleg: "Het is bijna pascha, en de Heere Jezus komt met Zijn discipelen bij Bethfagé aan de Olijfberg. Hij stuurt twee discipelen om een ezelin en haar veulen te halen. Als iemand iets vraagt, moeten ze zeggen dat de Heere ze nodig heeft. Ze leggen hun kleren op de dieren, en de Heere Jezus gaat erop zitten. Een grote menigte spreidt kleren en takken op de weg. De mensen roepen: ‘Hosanna den Zone Davids! Gezegend is Hij, Die komt in den Naam des Heeren! Hosanna in de hoogste hemelen!’ Als Hij Jeruzalem binnenkomt, raakt de hele stad in beroering: ‘Wie is Deze?’ De menigte antwoordt: ‘Deze is Jezus, de Profeet van Nazareth in Galilea.’",
  betekenis: "Mattheüs zegt zelf dat hier de profetie uitkwam: ‘Zie, uw Koning komt tot u, zachtmoedig en gezeten op een ezelin’ (Mattheüs 21:4–5; Zacharia 9:9). Lukas vertelt dat de Heere Jezus huilde toen Hij de stad zag, omdat zij niet begreep wat tot haar vrede diende (Lukas 19:41–42).",
  wie: ["Jezus", "Discipelen"], kw: "zachtmoedigheid",
  ontdek: { soort: "verbanden", titel: "Wat de Schrift al zei", items: [
    ["Zacharia 9:9", "‘Ziet, uw Koning zal u komen, rechtvaardig, en Hij is een Heiland; arm, en rijdende op een ezel.’", "Mattheüs 21:5–7", "De Heere Jezus rijdt op een ezelin met haar veulen Jeruzalem binnen."],
    ["Psalm 118:26", "‘Gezegend zij hij, die daar komt in den Naam des HEEREN!’", "Mattheüs 21:9", "De menigte roept: ‘Gezegend is Hij, Die komt in den Naam des Heeren!’"],
    ["Psalm 8:3", "‘Uit den mond der kinderkens en der zuigelingen hebt Gij sterkte gegrondvest.’", "Mattheüs 21:15–16", "Kinderen roepen Hosanna in de tempel, en de Heere Jezus wijst op deze psalm."]] },
  quiz: [{ q: "Bij welk dorp aan de Olijfberg liet de Heere Jezus de ezelin halen?", a: ["Bethfagé", "Bethlehem", "Kapernaüm"], why: "Mattheüs 21:1" },
    { q: "Wat moesten de discipelen zeggen als iemand vroeg waarom ze de dieren meenamen?", a: ["Dat de Heere ze nodig had", "Dat ze de dieren gingen kopen", "Dat de priesters het bevolen hadden"], why: "Mattheüs 21:3" },
    { q: "Wat spreidden de mensen op de weg?", a: ["Kleren en takken", "Gouden munten", "Rozen en lelies"], why: "Mattheüs 21:8" },
    { q: "Wat antwoordde de menigte op de vraag ‘Wie is Deze?’", a: ["Jezus, de Profeet van Nazareth in Galilea", "Johannes de Doper, die opgestaan is", "Elia, de profeet die terug zou komen"], why: "Mattheüs 21:11" }],
  cross: [["Zacharia 9:9", "De profetie over de Koning op een ezel."],
    ["Lukas 19:41–44", "Toen de Heere Jezus de stad zag, huilde Hij over haar."],
    ["Johannes 12:12–16", "Johannes vertelt over takken van palmbomen, en dat de discipelen het pas begrepen toen Jezus verheerlijkt was."]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Volgens Johannes 12:1 en 12:12 was de intocht de dag nadat de Heere Jezus, zes dagen voor het pascha, in Bethanië was gekomen." },

{ nr: 119, t: "De handelaars uit de tempel gejaagd", ref: "Mattheüs 21:12–17", sectie: "pasen", stappen: [S("nt-lijdensweek", 1)], vorm: "plek",
  uitleg: "In Jeruzalem gaat de Heere Jezus de tempel van God binnen. Daar wordt gekocht en verkocht. Hij jaagt de handelaars weg en gooit de tafels van de geldwisselaars en de stoelen van de duivenverkopers om. Hij zegt: ‘Er is geschreven: Mijn huis zal een huis des gebeds genaamd worden; maar gij hebt dat tot een moordenaarskuil gemaakt.’ Daarna komen blinden en kreupelen bij Hem in de tempel, en Hij geneest hen. Kinderen roepen in de tempel: ‘Hosanna den Zone Davids!’ De overpriesters en schriftgeleerden nemen dat zeer kwalijk. De Heere Jezus antwoordt met een psalm: uit de mond van jonge kinderen en zuigelingen heeft God Zich lof bereid. Dan gaat Hij de stad uit naar Bethanië en overnacht daar.",
  betekenis: "De woorden van de Heere Jezus komen uit Jesaja 56:7 (‘Mijn huis zal een bedehuis genoemd worden voor alle volken’) en Jeremia 7:11 (‘een spelonk der moordenaren’). Bij een eerdere tempelreiniging dachten de discipelen aan Psalm 69:10: ‘De ijver van Uw huis heeft mij verslonden’ (Johannes 2:17).",
  wie: ["Jezus", "Overpriesters", "Kinderen"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Mijn huis zal een huis des gebeds genaamd worden.", "De Heere Jezus", ["Kajafas", "Petrus"]],
    ["Hosanna den Zone Davids!", "De kinderen in de tempel", ["De handelaars", "De soldaten"]],
    ["Hoort Gij wel, wat dezen zeggen?", "De overpriesters en schriftgeleerden", ["De discipelen", "De blinden en kreupelen"]]] },
  quiz: [{ q: "Wiens tafels gooide de Heere Jezus om in de tempel?", a: ["Van de geldwisselaars", "Van de priesters", "Van de bakkers"], why: "Mattheüs 21:12" },
    { q: "Welke dieren werden er in de tempel verkocht, volgens Mattheüs 21?", a: ["Duiven", "Kamelen", "Paarden"], why: "Mattheüs 21:12" },
    { q: "Wie kwamen er in de tempel bij de Heere Jezus en werden genezen?", a: ["Blinden en kreupelen", "Melaatsen uit Samaria", "Soldaten van Pilatus"], why: "Mattheüs 21:14" },
    { q: "Waar overnachtte de Heere Jezus na de tempelreiniging?", a: ["In Bethanië", "In de tempel", "In Kapernaüm"], why: "Mattheüs 21:17" }],
  cross: [["Jesaja 56:7", "‘Mijn huis zal een bedehuis genoemd worden voor alle volken.’"],
    ["Jeremia 7:11", "‘Is dan dit huis ... in uw ogen een spelonk der moordenaren?’"],
    ["Johannes 2:13–17", "Ook aan het begin van Zijn openbare optreden dreef de Heere Jezus de handelaars uit de tempel."],
    ["Markus 11:15–18", "Markus vertelt het ook: daarna zochten de leiders hoe ze Hem konden doden."]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Mattheüs vertelt de tempelreiniging direct na de intocht; Markus 11:11–15 zegt dat het de volgende dag was." },

{ nr: 120, t: "Gelijkenissen over het Koninkrijk der hemelen", ref: "Mattheüs 22:1–25:46", sectie: "pasen", stappen: [S("nt-lijdensweek", 2), S("nt-lijdensweek", 3)], vorm: "gelijkenis",
  uitleg: "In Zijn laatste dagen in Jeruzalem leert de Heere Jezus veel over het Koninkrijk der hemelen. Het is als een koning die een bruiloft geeft voor zijn zoon. De genodigden willen niet komen, en dan worden mensen van de wegen binnengeroepen. Sommigen stellen Hem vragen om Hem te vangen, maar Hij geeft wijze antwoorden: geef de keizer wat van de keizer is, en God wat van God is. Het grote gebod is God liefhebben met heel je hart, en je naaste als jezelf. Op de Olijfberg zegt Hij dat de Zoon des mensen zal komen op de wolken van de hemel, op een dag die niemand weet. Daarom vertelt Hij over tien maagden. Vijf hebben olie bij zich en vijf niet, en als de bruidegom komt, gaat de deur dicht. Hij vertelt over dienstknechten die talenten krijgen om ermee te werken. En Hij vertelt hoe de Zoon des mensen als Koning alle volken zal scheiden, zoals een herder de schapen van de bokken scheidt.",
  betekenis: "De Heere Jezus geeft zelf de uitleg bij de tien maagden: ‘Zo waakt dan; want gij weet den dag niet, noch de ure, in dewelke de Zoon des mensen komen zal’ (Mattheüs 25:13). En bij de schapen en de bokken: ‘Voor zoveel gij dit een van deze Mijn minste broeders gedaan hebt, zo hebt gij dat Mij gedaan’ (Mattheüs 25:40).",
  wie: ["Jezus", "Discipelen", "Farizeeën", "Sadduceeën"],
  ontdek: { soort: "gelijkenis", titel: "Beeld en betekenis, zoals de Heere Jezus het Zelf zegt", beelden: [
    ["De bruiloft van de koningszoon", "‘Want velen zijn geroepen, maar weinigen uitverkoren.’", "Mattheüs 22:14"],
    ["De vijgeboom die blaadjes krijgt", "Dan weet je dat de zomer dichtbij is. ‘Alzo ook gijlieden, wanneer gij al deze dingen zult zien, zo weet, dat het nabij is.’", "Mattheüs 24:32–33"],
    ["Vijf wijze en vijf dwaze maagden", "‘Zo waakt dan; want gij weet den dag niet, noch de ure, in dewelke de Zoon des mensen komen zal.’", "Mattheüs 25:13"],
    ["De talenten", "Tegen de trouwe dienstknecht: ‘over weinig zijt gij getrouw geweest; over veel zal ik u zetten.’", "Mattheüs 25:21"],
    ["De schapen en de bokken", "‘Voor zoveel gij dit een van deze Mijn minste broeders gedaan hebt, zo hebt gij dat Mij gedaan.’", "Mattheüs 25:40"]] },
  quiz: [{ q: "Hoeveel talenten gaf de heer aan de eerste dienstknecht?", a: ["Vijf", "Twee", "Tien"], why: "Mattheüs 25:15" },
    { q: "Wat deed de dienstknecht die één talent had gekregen?", a: ["Hij verborg het in de aarde", "Hij gaf het aan de armen", "Hij won er tien bij"], why: "Mattheüs 25:18" },
    { q: "Wat is volgens de Heere Jezus het eerste en grote gebod?", a: ["God liefhebben met heel je hart, ziel en verstand", "Elke dag naar de tempel gaan", "Belasting betalen aan de keizer"], why: "Mattheüs 22:37–38" },
    { q: "Wie weet de dag en het uur waarop de Zoon des mensen komt?", a: ["Alleen de Vader", "De engelen", "De discipelen"], why: "Mattheüs 24:36" },
    { q: "Wat werd er om middernacht geroepen, toen de maagden sliepen?", a: ["Ziet, de bruidegom komt!", "Brand!", "De koning is gestorven!"], why: "Mattheüs 25:6" }],
  cross: [["Daniël 7:13–14", "Daniël zag ‘Een met de wolken des hemels, als eens mensen zoon’, Die het Koninkrijk kreeg."],
    ["Deuteronomium 6:5", "Het grote gebod staat al in de wet van Mozes."],
    ["1 Thessalonicenzen 4:16–17", "Paulus schrijft over de komst van de Heere uit de hemel."]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Dit onderwijs gaf de Heere Jezus in de laatste dagen voor het pascha (Mattheüs 26:1–2)." },

{ nr: 121, t: "De Meester wast de voeten", ref: "Lukas 22:24–27; Johannes 13:1–17", sectie: "pasen", stappen: [S("nt-lijdensweek", 5)], vorm: "plek",
  uitleg: "Het is de avond van het pascha. De Heere Jezus weet dat Zijn uur gekomen is om uit de wereld naar de Vader te gaan. Hij heeft de Zijnen lief tot het einde. Tijdens de maaltijd staat Hij op en legt Zijn kleren af. Hij doet een linnen doek om, giet water in een bekken en begint de voeten van de discipelen te wassen. Petrus wil dat eerst niet: ‘Gij zult mijn voeten niet wassen in der eeuwigheid!’ Maar de Heere Jezus zegt dat hij anders geen deel met Hem heeft. Dan zegt Petrus: niet alleen mijn voeten, maar ook mijn handen en mijn hoofd. Daarna vraagt de Heere Jezus: ‘Verstaat gij, wat Ik ulieden gedaan heb?’ Hij, de Heere en de Meester, heeft hun voeten gewassen; dus moeten zij ook elkaars voeten wassen. Lukas vertelt dat de discipelen die avond twistten over wie de grootste was. De Heere Jezus zegt: ‘de meeste onder u, die zij gelijk de minste.’",
  betekenis: "De Heere Jezus zegt: ‘Ik ben in het midden van u, als een die dient’ (Lukas 22:27). Eerder had Hij al gezegd: ‘Want ook de Zoon des mensen is niet gekomen om gediend te worden, maar om te dienen’ (Markus 10:45).",
  wie: ["Jezus", "Petrus", "Discipelen"],
  ontdek: { soort: "koppel", titel: "Wie deed wat?", paren: [
    ["De Heere Jezus", "Wast de voeten van de discipelen"], ["Petrus", "Zegt eerst: nooit mijn voeten!"],
    ["De discipelen", "Twisten over wie de grootste is"], ["De koningen der volken", "Heersen over hun volk"]] },
  quiz: [{ q: "Wat deed de Heere Jezus om voordat Hij de voeten waste?", a: ["Een linnen doek", "Een purperen mantel", "Een gouden gordel"], why: "Johannes 13:4" },
    { q: "Wat zei Petrus toen hij hoorde dat hij anders geen deel met de Heere Jezus had?", a: ["Niet alleen mijn voeten, maar ook de handen en het hoofd", "Dan wil ik liever Uw voeten wassen", "Dan moet U eerst Johannes wassen"], why: "Johannes 13:9" },
    { q: "Waarover twistten de discipelen op de avond van het pascha?", a: ["Wie van hen de meeste was", "Wie het brood mocht breken", "Wie het geld mocht bewaren"], why: "Lukas 22:24" },
    { q: "Waarom waste de Heere Jezus de voeten, volgens Zijn eigen woorden?", a: ["Als voorbeeld, opdat zij ook zo zouden doen", "Omdat er geen dienaar was", "Omdat het sabbat was"], why: "Johannes 13:15" }],
  cross: [["Markus 10:45", "‘De Zoon des mensen is niet gekomen om gediend te worden, maar om te dienen.’"],
    ["Filippenzen 2:5–8", "Christus nam de gestalte van een dienstknecht aan en vernederde Zichzelf tot de dood van het kruis."],
    ["Lukas 14:11", "‘Die zichzelven vernedert, zal verhoogd worden.’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Johannes 13:1 plaatst de voetwassing ‘voor het feest van het pascha’, op de avond van de laatste maaltijd." },

{ nr: 122, t: "Het Heilig Avondmaal", ref: "Lukas 22:7–23", sectie: "pasen", stappen: [S("nt-lijdensweek", 6)], vorm: "plek",
  uitleg: "Op de dag dat het paaslam geslacht moet worden, stuurt de Heere Jezus Petrus en Johannes om het pascha klaar te maken. Ze volgen een man met een kruik water naar een huis met een grote opperzaal. ’s Avonds zit de Heere Jezus aan tafel met de twaalf apostelen. ‘Ik heb grotelijks begeerd, dit pascha met u te eten, eer dat Ik lijde.’ Hij neemt brood, dankt, breekt het en geeft het hun: ‘Dat is Mijn lichaam, hetwelk voor u gegeven wordt; doet dat tot Mijn gedachtenis.’ Na de maaltijd neemt Hij de beker: ‘Deze drinkbeker is het nieuwe testament in Mijn bloed, hetwelk voor u vergoten wordt.’ Hij zegt ook dat de hand van Zijn verrader met Hem aan tafel is. De discipelen vragen elkaar wie dat zou kunnen zijn.",
  betekenis: "Bij het pascha herdachten de Israëlieten de uittocht uit Egypte, toen het bloed van het lam een teken was aan hun huizen (Exodus 12:13–14). Paulus schrijft: ‘ons Pascha is voor ons geslacht, namelijk Christus’ (1 Korinthe 5:7), en wie het avondmaal viert, verkondigt ‘den dood des Heeren, totdat Hij komt’ (1 Korinthe 11:26).",
  wie: ["Jezus", "Petrus", "Johannes", "Discipelen"], kw: "avondmaal",
  ontdek: { soort: "symbolen", titel: "Brood en beker: wat zegt de Bijbel zelf?", items: [
    ["Het brood", "‘Dat is Mijn lichaam, hetwelk voor u gegeven wordt.’", "Lukas 22:19"],
    ["De drinkbeker", "‘Deze drinkbeker is het nieuwe testament in Mijn bloed, hetwelk voor u vergoten wordt.’", "Lukas 22:20"],
    ["Doen tot gedachtenis", "‘Doet dat tot Mijn gedachtenis.’", "Lukas 22:19"],
    ["Het paaslam", "‘Ons Pascha is voor ons geslacht, namelijk Christus.’", "1 Korinthe 5:7"],
    ["Totdat Hij komt", "Zo dikwijls als de gemeente dit brood eet en de drinkbeker drinkt, verkondigt zij ‘den dood des Heeren, totdat Hij komt.’", "1 Korinthe 11:26"]] },
  quiz: [{ q: "Welke twee discipelen moesten het pascha klaarmaken?", a: ["Petrus en Johannes", "Thomas en Filippus", "Judas en Andreas"], why: "Lukas 22:8" },
    { q: "Wie moesten Petrus en Johannes volgen in de stad?", a: ["Een man met een kruik water", "Een priester met een lam", "Een kind met een lamp"], why: "Lukas 22:10" },
    { q: "Wat zei de Heere Jezus toen Hij het brood gaf?", a: ["Dat is Mijn lichaam, hetwelk voor u gegeven wordt", "Dit is het manna uit de hemel", "Eet en wees verzadigd"], why: "Lukas 22:19" },
    { q: "Wanneer gaf de Heere Jezus de drinkbeker van het nieuwe testament?", a: ["Na het avondmaal", "Voor het eten", "De volgende morgen"], why: "Lukas 22:20" }],
  cross: [["Exodus 12:13–14", "Het bloed van het paaslam was een teken, en de dag moest gevierd worden ‘ter gedachtenis’."],
    ["1 Korinthe 11:23–26", "Paulus geeft door wat hij van de Heere ontvangen heeft over het avondmaal."],
    ["Mattheüs 26:26–29", "Mattheüs: ‘het bloed des Nieuwen Testaments, hetwelk voor velen vergoten wordt, tot vergeving der zonden.’"],
    ["Johannes 6:35", "‘Ik ben het Brood des levens.’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Lukas 22:7 noemt ‘de dag der ongehevelde broden … op denwelken het pascha moest geslacht worden’." },

{ nr: 123, t: "Het verraad in Gethsémané", ref: "Markus 14:10–11, 26–50", sectie: "pasen", stappen: [S("nt-lijdensweek", 4), S("nt-lijdensweek", 7), S("nt-lijdensweek", 8)], vorm: "route",
  uitleg: "Judas Iskariot, een van de twaalf, gaat naar de overpriesters om de Heere Jezus aan hen over te leveren. Zij zijn blij en beloven hem geld. Vanaf dan zoekt hij een goede gelegenheid. Na de lofzang gaat de Heere Jezus met Zijn discipelen naar de Olijfberg, naar een plaats die Gethsémané heet. Hij neemt Petrus, Jakobus en Johannes mee, en Hij is diep bedroefd. Hij bidt: ‘Abba, Vader! alle dingen zijn U mogelijk; neem dezen drinkbeker van Mij weg, doch niet wat Ik wil, maar wat Gij wilt.’ Steeds als Hij terugkomt, slapen de discipelen. Dan komt Judas met een grote groep met zwaarden en stokken. Hij zegt: ‘Rabbi’, en kust Hem; dat was het afgesproken teken. Ze grijpen de Heere Jezus, en iemand slaat met een zwaard de dienstknecht van de hogepriester een oor af. Dan verlaten alle discipelen Hem en vluchten.",
  betekenis: "De Heere Jezus zegt zelf dat dit gebeurt ‘opdat de Schriften vervuld zouden worden’ (Markus 14:49). Over Zijn verrader haalt Hij Psalm 41:10 aan: ‘Die met Mij het brood eet, heeft tegen Mij zijn verzenen opgeheven’ (Johannes 13:18).",
  wie: ["Jezus", "Judas Iskariot", "Petrus", "Jakobus", "Johannes"],
  ontdek: { soort: "volgorde", titel: "Wat gebeurde er eerst?", items: ["Judas gaat naar de overpriesters", "De lofzang, op naar de Olijfberg", "Bidden in Gethsémané", "Judas geeft een kus", "De discipelen vluchten"] },
  quiz: [{ q: "Wat beloofden de overpriesters aan Judas?", a: ["Geld", "Een plaats in de raad", "Een huis in Jeruzalem"], why: "Markus 14:11" },
    { q: "Met welke woorden sprak de Heere Jezus God aan in Gethsémané?", a: ["Abba, Vader", "Koning der koningen", "God van Israël"], why: "Markus 14:36" },
    { q: "Wat vroeg de Heere Jezus aan Simon Petrus toen Hij hem slapend vond?", a: ["Kunt gij niet een uur waken?", "Waar is uw zwaard?", "Hebt gij Mij lief?"], why: "Markus 14:37" },
    { q: "Wat zei Judas toen hij de Heere Jezus kuste?", a: ["Rabbi", "Vrede zij U", "Gegroet, Koning"], why: "Markus 14:45" }],
  cross: [["Psalm 41:10", "‘Zelfs de man mijns vredes ... die mijn brood at, heeft de verzenen tegen mij grotelijks verheven.’"],
    ["Zacharia 13:7", "‘Sla dien Herder, en de schapen zullen verstrooid worden.’ De Heere Jezus haalt dit aan (Markus 14:27)."],
    ["Lukas 22:43–44", "Een engel uit de hemel versterkte Hem, en Zijn zweet werd als grote druppels bloed."]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Het verraad gebeurde in de nacht na de paasmaaltijd (Markus 14:12–17, 26)." },

{ nr: 124, t: "Petrus verloochent de Heere Jezus", ref: "Mattheüs 26:31–35, 57–75", sectie: "pasen", stappen: [S("nt-lijden", 0), S("nt-lijden", 1)], vorm: "plek",
  uitleg: "Op weg naar de Olijfberg zegt de Heere Jezus dat de discipelen Hem die nacht allemaal zullen verlaten. Petrus zegt: ‘Al werden zij ook allen aan U geërgerd, ik zal nimmermeer geërgerd worden.’ De Heere Jezus antwoordt dat Petrus Hem die nacht, voordat de haan kraait, driemaal zal verloochenen. Na de gevangenneming volgt Petrus van ver tot in het huis van de hogepriester Kajafas en gaat bij de dienaren zitten. Een dienstmeisje zegt: ‘Gij waart ook met Jezus, den Galileër’, maar Petrus ontkent het. Een ander meisje zegt het ook, en hij zweert: ‘Ik ken den Mens niet.’ Als omstanders zeggen dat zijn spraak hem verraadt, vervloekt hij zichzelf en zweert opnieuw. Meteen kraait de haan. Petrus denkt aan het woord van de Heere Jezus, gaat naar buiten en huilt bitter.",
  betekenis: "De Heere Jezus wist het van tevoren en had voor Petrus gebeden, ‘dat uw geloof niet ophoude’ (Lukas 22:32). Na de opstanding vraagt Hij hem driemaal: ‘Hebt gij Mij lief?’ (Johannes 21:15–17).",
  wie: ["Petrus", "Jezus", "Kajafas"],
  ontdek: { soort: "onthul", titel: "Driemaal, en dan de haan", items: [
    ["De eerste keer", "Een dienstmaagd: ‘Gij waart ook met Jezus, den Galileër.’ Petrus: ‘Ik weet niet, wat gij zegt’ (Mattheüs 26:69–70)."],
    ["De tweede keer", "Een andere dienstmaagd bij de voorpoort: ‘Deze was ook met Jezus den Nazarener.’ Petrus zweert: ‘Ik ken den Mens niet’ (26:71–72)."],
    ["De derde keer", "Omstanders: ‘ook uw spraak maakt u openbaar.’ Petrus vervloekt zichzelf en zweert (26:73–74)."],
    ["De haan", "Meteen kraait de haan. Lukas vertelt: de Heere keert Zich om en ziet Petrus aan (Lukas 22:61)."],
    ["Bittere tranen", "Petrus denkt aan Zijn woord, gaat naar buiten en huilt bitter (Mattheüs 26:75)."]] },
  quiz: [{ q: "Wat zei Petrus toen de Heere Jezus zei dat hij Hem zou verloochenen?", a: ["Al moest ik ook met U sterven, zo zal ik U geenszins verloochenen", "Dan vluchten we samen naar Galilea", "Ik ga terug naar mijn netten"], why: "Mattheüs 26:35" },
    { q: "Wie zei als eerste tegen Petrus dat hij bij de Heere Jezus hoorde?", a: ["Een dienstmaagd", "Kajafas", "Een soldaat"], why: "Mattheüs 26:69" },
    { q: "Waaraan hoorden de omstanders dat Petrus bij de discipelen hoorde?", a: ["Aan zijn spraak", "Aan zijn kleren", "Aan zijn zwaard"], why: "Mattheüs 26:73" },
    { q: "Wat deed Petrus toen de haan gekraaid had?", a: ["Hij ging naar buiten en huilde bitter", "Hij rende naar Gethsémané", "Hij ging naar Pilatus"], why: "Mattheüs 26:75" }],
  cross: [["Lukas 22:31–34", "‘Simon, Simon ... Ik heb voor u gebeden, dat uw geloof niet ophoude.’"],
    ["Lukas 22:61–62", "De Heere keerde Zich om en zag Petrus aan."],
    ["Johannes 21:15–17", "Driemaal vraagt de opgestane Heere: ‘Hebt gij Mij lief?’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Dit gebeurde in de nacht van het verhoor, voordat de haan kraaide (Mattheüs 26:34, 74)." },

{ nr: 125, t: "Voor Pilatus: Kruis Hem!", ref: "Lukas 22:66–23:25", sectie: "pasen", stappen: [S("nt-lijden", 3), S("nt-lijden", 4), S("nt-lijden", 5)], vorm: "plek",
  uitleg: "Als het dag wordt, brengen de oudsten, overpriesters en schriftgeleerden de Heere Jezus voor hun raad. Ze vragen: ‘Zijt Gij dan de Zoon Gods?’ Hij antwoordt: ‘Gij zegt, dat Ik het ben.’ Dan brengen ze Hem naar Pilatus en beschuldigen Hem. Ze zeggen dat Hij het volk op een verkeerde weg brengt en zegt dat Hij Christus, een Koning, is. Pilatus ondervraagt Hem en zegt: ‘Ik vind geen schuld in dezen Mens.’ Hij stuurt Hem naar Herodes. Maar ook Herodes vindt niets wat de dood verdient, en hij stuurt Hem terug. Pilatus wil Hem laten kastijden en loslaten. Maar de hele menigte roept: ‘Weg met Dezen, en laat ons Bar-abbas los’, en daarna: ‘Kruis Hem, kruis Hem!’ Driemaal zegt Pilatus dat hij geen schuld in Hem vindt, maar hun geroep wordt steeds sterker. Dan laat Pilatus Barabbas vrij, en hij geeft de Heere Jezus over aan hun wil.",
  betekenis: "Tegen Pilatus zegt de Heere Jezus: ‘Hiertoe ben Ik geboren, en hiertoe ben Ik in de wereld gekomen, opdat Ik der waarheid getuigenis geven zou’ (Johannes 18:37). Petrus schrijft later: ‘Die, als Hij gescholden werd, niet wederschold, en als Hij leed, niet dreigde’ (1 Petrus 2:23).",
  wie: ["Jezus", "Pilatus", "Herodes Antipas", "Barabbas"], kw: "waarheid",
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Wat is waarheid?", "Pilatus", ["Herodes", "Kajafas"]],
    ["Mijn Koninkrijk is niet van deze wereld.", "De Heere Jezus", ["Petrus", "Pilatus"]],
    ["Heb toch niet te doen met dien Rechtvaardige.", "De vrouw van Pilatus", ["Maria Magdalena", "Een dienstmaagd"]],
    ["Wij hebben geen koning, dan den keizer.", "De overpriesters", ["De discipelen", "De soldaten"]],
    ["Ziet, de Mens!", "Pilatus", ["De hoofdman", "Herodes"]]] },
  quiz: [{ q: "Naar wie stuurde Pilatus de Heere Jezus toen hij hoorde dat Hij uit Galilea kwam?", a: ["Naar Herodes", "Naar de keizer", "Naar Annas"], why: "Lukas 23:7" },
    { q: "Wat gebeurde er op die dag tussen Pilatus en Herodes?", a: ["Ze werden vrienden", "Ze kregen ruzie", "Ze lieten de Heere Jezus samen vrij"], why: "Lukas 23:12" },
    { q: "Waarom zat Barabbas in de gevangenis?", a: ["Om oproer en moord", "Om diefstal van een ezel", "Omdat hij geen belasting betaalde"], why: "Lukas 23:19" },
    { q: "Hoe vaak zei Pilatus volgens Lukas dat hij geen schuld in de Heere Jezus vond?", a: ["Driemaal", "Eenmaal", "Zevenmaal"], why: "Lukas 23:22" }],
  cross: [["Johannes 18:37–38", "‘Een iegelijk, die uit de waarheid is, hoort Mijn stem.’ Pilatus: ‘Wat is waarheid?’"],
    ["Johannes 14:6", "‘Ik ben de Weg, en de Waarheid, en het Leven.’"],
    ["Jesaja 53:7", "‘Als een lam werd Hij ter slachting geleid ... alzo deed Hij Zijn mond niet open.’"],
    ["Mattheüs 27:24", "Pilatus wast zijn handen voor het volk."]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Het verhoor bij Pilatus was ’s morgens vroeg (Lukas 22:66; Johannes 18:28)." },

{ nr: 126, t: "Gekruisigd op Golgotha", ref: "Johannes 19:16–30", sectie: "pasen", stappen: [S("nt-lijden", 6), S("nt-lijden", 7)], vorm: "plek",
  uitleg: "Pilatus geeft de Heere Jezus over om gekruisigd te worden. Hij draagt Zijn kruis en gaat naar de plaats die Hoofdschedelplaats heet, in het Hebreeuws Golgotha. Daar kruisigen ze Hem, met twee anderen, aan elke kant één, en Hij in het midden. Pilatus laat op het kruis schrijven: ‘JEZUS, DE NAZARENER, DE KONING DER JODEN’, in het Hebreeuws, het Grieks en het Latijn. De soldaten verdelen Zijn kleren en loten om Zijn rok, die uit één stuk geweven is. Bij het kruis staan Zijn moeder, de zuster van Zijn moeder, Maria de vrouw van Klopas, en Maria Magdalena. De Heere Jezus vertrouwt Zijn moeder toe aan de discipel die Hij liefhad. Hij weet dat alles nu volbracht is, en Hij zegt: ‘Mij dorst.’ Als Hij de edik genomen heeft, zegt Hij: ‘Het is volbracht!’ Hij buigt Zijn hoofd en geeft de geest.",
  betekenis: "Johannes laat zien dat zo de Schrift vervuld werd: ‘Zij hebben Mijn klederen onder zich verdeeld’ (Johannes 19:24; Psalm 22:19). Paulus schrijft dat Christus ‘gehoorzaam geworden’ is ‘tot den dood, ja, den dood des kruises’ (Filippenzen 2:8), en Petrus dat Hij ‘onze zonden in Zijn lichaam gedragen heeft op het hout’ (1 Petrus 2:24).",
  wie: ["Jezus", "Maria", "Maria Magdalena", "Pilatus"], kw: "kruis",
  ontdek: { soort: "verbanden", titel: "Wat de Schrift al zei", items: [
    ["Psalm 22:19", "‘Zij delen mijn klederen onder zich, en werpen het lot over mijn gewaad.’", "Johannes 19:23–24", "De soldaten verdelen Zijn kleren en loten om Zijn rok."],
    ["Psalm 69:22", "‘In mijn dorst hebben zij mij edik te drinken gegeven.’", "Johannes 19:28–29", "Hij zegt ‘Mij dorst’, en ze brengen Hem een spons met edik."],
    ["Psalm 22:2", "‘Mijn God, mijn God! waarom hebt Gij mij verlaten?’", "Mattheüs 27:46", "Omtrent het negende uur roept de Heere Jezus deze woorden met een grote stem."],
    ["Jesaja 53:12", "‘Hij ... met de overtreders is geteld geweest ... en voor de overtreders gebeden heeft.’", "Lukas 23:33–34", "Hij wordt gekruisigd tussen kwaaddoeners en bidt: ‘Vader, vergeef het hun.’"]] },
  quiz: [{ q: "Wat betekent de naam Golgotha?", a: ["Hoofdschedelplaats", "Olijfberg", "Akker des bloeds"], why: "Johannes 19:17" },
    { q: "In welke talen stond het opschrift op het kruis?", a: ["Hebreeuws, Grieks en Latijn", "Hebreeuws, Arabisch en Egyptisch", "Alleen in het Latijn"], why: "Johannes 19:20" },
    { q: "Waarom scheurden de soldaten de rok van de Heere Jezus niet?", a: ["Hij was zonder naad, uit één stuk geweven", "Hij was van goud", "Pilatus had het verboden"], why: "Johannes 19:23–24" },
    { q: "Wat zei de Heere Jezus aan het kruis tegen de discipel die Hij liefhad?", a: ["Zie, uw moeder", "Ga naar Galilea", "Waak en bid"], why: "Johannes 19:27" }],
  cross: [["Psalm 22:2", "De psalm die begint met de woorden die de Heere Jezus aan het kruis riep."],
    ["Jesaja 53:4–5", "‘Hij is om onze overtredingen verwond, om onze ongerechtigheden is Hij verbrijzeld.’"],
    ["Filippenzen 2:8", "‘Gehoorzaam geworden zijnde tot den dood, ja, den dood des kruises.’"],
    ["Johannes 3:14–16", "Zoals Mozes de slang verhoogde in de woestijn, zo moest de Zoon des mensen verhoogd worden."]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Het was ‘de voorbereiding van het pascha’ (Johannes 19:14); de duisternis duurde van het zesde tot het negende uur (Mattheüs 27:45)." },

{ nr: 127, t: "De begrafenis van de Heere Jezus", ref: "Johannes 19:31–42", sectie: "pasen", stappen: [S("nt-lijden", 8)], vorm: "plek",
  uitleg: "Het is de dag van de voorbereiding, en de sabbat die volgt is een grote dag. De Joden vragen Pilatus of de benen van de gekruisigden gebroken mogen worden, zodat de lichamen weggehaald kunnen worden. De soldaten breken de benen van de twee anderen. Maar ze zien dat de Heere Jezus al gestorven is, en daarom breken ze Zijn benen niet. Wel doorsteekt één soldaat Zijn zijde met een speer, en meteen komt er bloed en water uit. Wie het gezien heeft, getuigt dat het waar is. Dan vraagt Jozef van Arimathea Pilatus om het lichaam. Hij was een discipel, maar uit angst voor de Joden in het verborgen. Nicodemus komt met ongeveer honderd pond mirre en aloë. Samen wikkelen ze het lichaam met de specerijen in linnen doeken. In een hof dicht bij de plaats van de kruisiging is een nieuw graf, waar nog nooit iemand in gelegen heeft. Daar leggen ze de Heere Jezus.",
  betekenis: "Johannes schrijft dat zo twee Schriftwoorden vervuld werden: ‘Geen been van Hem zal verbroken worden’ en ‘Zij zullen zien, in Welken zij gestoken hebben’ (Johannes 19:36–37; Exodus 12:46; Zacharia 12:10). Paulus noemt de begrafenis in het evangelie dat hij doorgaf: ‘dat Hij is begraven’ (1 Korinthe 15:4).",
  wie: ["Jozef van Arimathea", "Nicodemus", "Pilatus"],
  ontdek: { soort: "koppel", titel: "Wie deed wat?", paren: [
    ["Jozef van Arimathea", "Vroeg Pilatus om het lichaam"], ["Nicodemus", "Bracht ongeveer honderd pond mirre en aloë"],
    ["Een soldaat", "Doorstak Zijn zijde met een speer"], ["De Joden", "Wilden de lichamen niet op de sabbat aan het kruis laten"]] },
  quiz: [{ q: "Waarom braken de soldaten de benen van de Heere Jezus niet?", a: ["Hij was al gestorven", "Pilatus verbood het", "Ze waren te bang"], why: "Johannes 19:33" },
    { q: "Wat kwam er uit Zijn zijde toen een soldaat er een speer in stak?", a: ["Bloed en water", "Alleen water", "Niets"], why: "Johannes 19:34" },
    { q: "Waarom was Jozef van Arimathea eerst een verborgen discipel?", a: ["Uit vrees voor de Joden", "Omdat hij een Romein was", "Omdat de Heere Jezus het vroeg"], why: "Johannes 19:38" },
    { q: "Wat was er bijzonder aan het graf in de hof?", a: ["Er was nog nooit iemand in gelegd", "Het was van goud", "Het lag in de tempel"], why: "Johannes 19:41" }],
  cross: [["Jesaja 53:9", "‘Hij is bij den rijke in Zijn dood geweest.’"],
    ["Mattheüs 27:57–66", "Mattheüs: een grote steen voor de deur, de vrouwen tegenover het graf, en een verzegelde steen met een wacht."],
    ["1 Korinthe 15:3–4", "‘Dat Christus gestorven is voor onze zonden, naar de Schriften; En dat Hij is begraven.’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " De begrafenis was op de voorbereiding, vlak voor de sabbat (Johannes 19:31, 42; Lukas 23:54)." },

{ nr: 128, t: "Het lege graf en de engel", ref: "Mattheüs 28:1–8", sectie: "pasen", stappen: [S("nt-opstanding", 0)], vorm: "plek",
  uitleg: "Na de sabbat, als de eerste dag van de week begint te lichten, gaan Maria Magdalena en de andere Maria naar het graf. De overpriesters hadden het graf laten verzegelen en bewaken. Dan komt er een grote aardbeving. Een engel van de Heere daalt uit de hemel neer, rolt de steen van de ingang weg en gaat erop zitten. Hij ziet eruit als een bliksem, en zijn kleding is wit als sneeuw. De wachters beven van angst en worden als doden. De engel zegt tegen de vrouwen: ‘Vreest gijlieden niet; want ik weet, dat gij zoekt Jezus, Die gekruisigd was. Hij is hier niet; want Hij is opgestaan, gelijk Hij gezegd heeft.’ Hij laat hun de plaats zien waar de Heere gelegen heeft. Dan stuurt hij hen naar de discipelen: Hij gaat u voor naar Galilea. Met vrees en grote blijdschap rennen ze weg om het te vertellen.",
  betekenis: "De engel zegt: ‘gelijk Hij gezegd heeft.’ De Heere Jezus had het vooruit gezegd: Hij zou gedood worden ‘en ten derden dage opgewekt worden’ (Mattheüs 16:21).",
  wie: ["Maria Magdalena", "Engel", "Wachters"],
  ontdek: { soort: "kaart", titel: "Waar was het lege graf?", vraag: "Het graf lag in een hof, vlak bij de plaats waar de Heere Jezus gekruisigd werd, dicht bij de stad (Johannes 19:20, 41). Wijs Jeruzalem aan op de kaart.", id: "salem", v: "kanaan" },
  quiz: [{ q: "Wanneer gingen Maria Magdalena en de andere Maria naar het graf?", a: ["Toen het licht begon te worden op de eerste dag van de week", "Op de avond van de sabbat", "Midden in de nacht van de voorbereiding"], why: "Mattheüs 28:1" },
    { q: "Hoe zag de kleding van de engel eruit?", a: ["Wit als sneeuw", "Rood als bloed", "Zwart als de nacht"], why: "Mattheüs 28:3" },
    { q: "Wat gebeurde er met de wachters toen de engel kwam?", a: ["Ze werden als doden van angst", "Ze vielen in slaap", "Ze vochten met de engel"], why: "Mattheüs 28:4" },
    { q: "Waarheen zou de opgestane Heere de discipelen voorgaan?", a: ["Naar Galilea", "Naar Bethlehem", "Naar Rome"], why: "Mattheüs 28:7" }],
  cross: [["Mattheüs 16:21", "De Heere Jezus had gezegd dat Hij ten derden dage opgewekt zou worden."],
    ["Markus 16:1–8", "Markus noemt ook Salome; de vrouwen vroegen zich af wie de steen zou wegrollen."],
    ["Lukas 24:1–8", "Lukas: twee mannen in blinkende klederen: ‘Wat zoekt gij den Levende bij de doden?’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " De tekst noemt de dag: ‘tegen den eersten dag der week’ (Mattheüs 28:1)." },

{ nr: 129, t: "De Heere is opgestaan", ref: "Mattheüs 28:9–15; Johannes 20:1–18", sectie: "pasen", stappen: [S("nt-opstanding", 0), S("nt-opstanding", 1)], vorm: "plek",
  uitleg: "Als de vrouwen van het graf weglopen, komt de Heere Jezus Zelf hen tegemoet: ‘Weest gegroet!’ Ze grijpen Zijn voeten en aanbidden Hem. ‘Vreest niet; gaat henen, boodschapt Mijn broederen, dat zij heengaan naar Galilea.’ Maria Magdalena vertelt Petrus en de andere discipel dat het graf leeg is. Zij rennen erheen en zien de linnen doeken liggen. Maria blijft huilend bij het graf staan. Ze ziet iemand van wie ze denkt dat het de hovenier is, totdat Hij haar bij haar naam noemt: ‘Maria!’ ‘Rabbouni!’, zegt ze: Meester. Ze gaat naar de discipelen: ze heeft de Heere gezien. Ondertussen geven de overpriesters de soldaten van de wacht veel geld om te zeggen dat de discipelen het lichaam gestolen hebben.",
  betekenis: "Paulus noemt veel mensen die de opgestane Heere gezien hebben, ‘van welken het meren deel nog over is’ (1 Korinthe 15:5–6). En hij schrijft: ‘Christus is opgewekt uit de doden, en is de Eersteling geworden dergenen, die ontslapen zijn’ (1 Korinthe 15:20).",
  wie: ["Jezus", "Maria Magdalena", "Petrus"], kw: "opstanding",
  ontdek: { soort: "onthul", titel: "Wie hebben Hem gezien?", items: [
    ["Maria Magdalena", "Bij het graf hoort ze haar naam: ‘Maria!’ (Johannes 20:16)."],
    ["De vrouwen", "Onderweg komt Hij hen tegemoet: ‘Weest gegroet!’ (Mattheüs 28:9)."],
    ["Simon Petrus (Cefas)", "‘De Heere is waarlijk opgestaan, en is van Simon gezien’ (Lukas 24:34; 1 Korinthe 15:5)."],
    ["De twee uit Emmaüs", "Ze herkennen Hem bij het breken van het brood (Lukas 24:30–31)."],
    ["De discipelen, en later Thomas", "‘Vrede zij ulieden!’ (Johannes 20:19, 26)."],
    ["Meer dan vijfhonderd broeders", "Allemaal tegelijk (1 Korinthe 15:6)."],
    ["Jakobus, alle apostelen, en ten slotte Paulus", "1 Korinthe 15:7–8."]] },
  quiz: [{ q: "Wat deden de vrouwen toen de Heere Jezus hen tegemoet kwam?", a: ["Ze grepen Zijn voeten en aanbaden Hem", "Ze vluchtten weg", "Ze riepen de soldaten"], why: "Mattheüs 28:9" },
    { q: "Wat moesten de soldaten van de overpriesters zeggen?", a: ["Dat de discipelen het lichaam ’s nachts gestolen hadden", "Dat er een engel was gekomen", "Dat het graf nooit gebruikt was"], why: "Mattheüs 28:13" },
    { q: "Wie kwam als eerste bij het graf toen Petrus en de andere discipel erheen liepen?", a: ["De andere discipel", "Petrus", "Maria, de vrouw van Klopas"], why: "Johannes 20:4" },
    { q: "Wat betekent ‘Rabbouni’?", a: ["Meester", "Vriend", "Koning"], why: "Johannes 20:16" }],
  cross: [["1 Korinthe 15:3–8", "Het evangelie dat Paulus doorgaf: gestorven, begraven, opgewekt, en gezien door veel getuigen."],
    ["Psalm 16:10", "‘Gij zult niet toelaten, dat Uw Heilige de verderving zie.’"],
    ["Romeinen 4:25", "‘Welke overgeleverd is om onze zonden, en opgewekt om onze rechtvaardigmaking.’"],
    ["Johannes 11:25", "‘Ik ben de Opstanding en het Leven.’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Op de eerste dag van de week, de derde dag na de kruisiging (Johannes 20:1; Lukas 24:21)." },

{ nr: 130, t: "De Emmaüsgangers", ref: "Lukas 24:13–35", sectie: "pasen", stappen: [S("nt-opstanding", 2)], vorm: "route",
  uitleg: "Op de dag van de opstanding lopen twee discipelen van Jeruzalem naar Emmaüs, een dorp op zestig stadiën afstand. Ze praten verdrietig over alles wat er gebeurd is. De Heere Jezus komt bij hen lopen, maar hun ogen worden gehouden, zodat ze Hem niet herkennen. Kleopas vertelt Hem over Jezus van Nazareth, Die gekruisigd is, en over de vrouwen die zeiden dat Hij leeft. De Heere Jezus zegt: ‘O onverstandigen en tragen van hart, om te geloven al hetgeen de profeten gesproken hebben!’ Beginnend bij Mozes en alle profeten legt Hij uit wat in de Schriften over Hem geschreven staat. In Emmaüs blijft Hij bij hen eten. Als Hij het brood breekt, gaan hun ogen open en herkennen ze Hem. Dan verdwijnt Hij uit hun gezicht. ‘Was ons hart niet brandende in ons?’ Nog dezelfde avond gaan ze terug naar Jeruzalem. Daar zeggen de elf: ‘De Heere is waarlijk opgestaan, en is van Simon gezien.’",
  betekenis: "De Heere Jezus laat Zelf zien dat de Schriften over Hem spreken: ‘Moest de Christus niet deze dingen lijden, en alzo in Zijn heerlijkheid ingaan?’ (Lukas 24:26–27). Later zegt Hij tegen de elf dat alles vervuld moest worden wat over Hem geschreven is in de Wet van Mozes, de Profeten en de Psalmen (Lukas 24:44).",
  wie: ["Kleopas", "Jezus"],
  ontdek: { soort: "volgorde", titel: "Zet de weg naar Emmaüs in volgorde", items: ["Verdrietig op weg", "Een Vreemdeling loopt mee", "De Schriften uitgelegd", "Blijf met ons", "Het brood gebroken", "Terug naar Jeruzalem"] },
  quiz: [{ q: "Hoe heette een van de twee discipelen die naar Emmaüs liepen?", a: ["Kleopas", "Nathanaël", "Zacheüs"], why: "Lukas 24:18" },
    { q: "Waarmee begon de Heere Jezus toen Hij de Schriften uitlegde?", a: ["Met Mozes en al de profeten", "Met de Psalmen van Asaf", "Met het boek Ruth"], why: "Lukas 24:27" },
    { q: "Waarom vroegen de twee de Heere Jezus om bij hen te blijven?", a: ["Het was bij de avond", "Het regende", "Hij was moe"], why: "Lukas 24:29" },
    { q: "Wat zeiden de twee tegen elkaar nadat Hij verdwenen was?", a: ["Was ons hart niet brandende in ons?", "Wij hebben een geest gezien", "Laat ons naar Galilea gaan"], why: "Lukas 24:32" }],
  cross: [["Lukas 24:44–47", "Alles moest vervuld worden wat in de Wet, de Profeten en de Psalmen over Hem geschreven is."],
    ["Jesaja 53:3–5", "Jesaja schreef over de Man van smarten, Die om onze overtredingen verwond werd."],
    ["1 Korinthe 15:5", "‘Hij is van Cefas gezien, daarna van de twaalven.’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " De tekst noemt de dag: ‘heden de derde dag, van dat deze dingen geschied zijn’ (Lukas 24:21)." },

{ nr: 131, t: "Thomas ziet en gelooft", ref: "Johannes 20:19–31", sectie: "pasen", stappen: [S("nt-opstanding", 3), S("nt-opstanding", 4)], vorm: "plek",
  uitleg: "Op de avond van de eerste dag van de week zijn de discipelen bij elkaar, met de deuren dicht uit vrees voor de Joden. De Heere Jezus komt en staat in hun midden: ‘Vrede zij ulieden!’ Hij laat Zijn handen en Zijn zijde zien, en de discipelen worden blij als ze de Heere zien. Hij zendt hen, zoals de Vader Hem gezonden heeft. Hij blaast op hen en zegt: ‘Ontvangt den Heiligen Geest.’ Thomas is er niet bij. De anderen vertellen dat ze de Heere gezien hebben. Maar Thomas zegt dat hij het pas gelooft als hij het teken van de nagels ziet en aanraakt. Acht dagen later komt de Heere Jezus weer, terwijl de deuren gesloten zijn. Nu is Thomas erbij. ‘Breng uw vinger hier, en zie Mijn handen ... en zijt niet ongelovig, maar gelovig.’ Thomas antwoordt: ‘Mijn Heere en mijn God!’",
  betekenis: "Johannes schrijft zelf waarom hij dit vertelt: ‘opdat gij gelooft, dat Jezus is de Christus, de Zone Gods; en opdat gij, gelovende, het leven hebt in Zijn Naam’ (Johannes 20:31). Petrus schrijft over gelovigen die de Heere niet gezien hebben en Hem toch liefhebben (1 Petrus 1:8).",
  wie: ["Thomas", "Jezus", "Discipelen"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Vrede zij ulieden!", "De Heere Jezus", ["Thomas", "Petrus"]],
    ["Wij hebben den Heere gezien.", "De andere discipelen", ["Thomas", "De Joden"]],
    ["Mijn Heere en mijn God!", "Thomas", ["Petrus", "Maria Magdalena"]],
    ["Zalig zijn zij, die niet zullen gezien hebben, en nochtans zullen geloofd hebben.", "De Heere Jezus", ["Johannes", "Thomas"]]] },
  quiz: [{ q: "Waarom waren de deuren dicht toen de discipelen bij elkaar waren?", a: ["Uit vrees voor de Joden", "Omdat het koud was", "Omdat het sabbat was"], why: "Johannes 20:19" },
    { q: "Wat liet de Heere Jezus de discipelen zien op de eerste avond?", a: ["Zijn handen en Zijn zijde", "Een brief van Pilatus", "De linnen doeken"], why: "Johannes 20:20" },
    { q: "Hoeveel dagen later zag Thomas de Heere Jezus?", a: ["Acht dagen", "Drie dagen", "Veertig dagen"], why: "Johannes 20:26" },
    { q: "Welke bijnaam had Thomas?", a: ["Didymus", "Cefas", "Barsabas"], why: "Johannes 20:24" }],
  cross: [["1 Petrus 1:8", "‘Denwelken gij niet gezien hebt, en nochtans liefhebt.’"],
    ["Lukas 24:36–43", "Lukas vertelt ook over die avond: de Heere Jezus at een stuk gebraden vis voor hun ogen."],
    ["Johannes 11:16", "Thomas had eerder gezegd: ‘Laat ons ook gaan, opdat wij met Hem sterven.’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " De eerste avond was de dag van de opstanding; Thomas zag Hem ‘na acht dagen’ (Johannes 20:19, 26)." },

{ nr: 132, t: "De Heere Jezus en Petrus bij het meer", ref: "Johannes 21:1–19", sectie: "pasen", stappen: [S("nt-opstanding", 5), S("nt-opstanding", 6)], vorm: "plek",
  uitleg: "Daarna laat de Heere Jezus Zich weer zien aan de zee van Tiberias. Petrus gaat met zes andere discipelen vissen, maar die nacht vangen ze niets. ’s Morgens staat de Heere Jezus op de oever. Hij zegt dat ze het net aan de rechterkant van het schip moeten uitwerpen. Nu zit het net zo vol dat ze het niet kunnen binnenhalen. ‘Het is de Heere!’, zegt de discipel die Jezus liefhad, en Petrus springt in het water. Op de oever ligt een kolenvuur met vis en brood, en de Heere Jezus geeft hun te eten. Na het eten vraagt Hij Petrus driemaal: ‘Simon, zoon van Jonas, hebt gij Mij lief?’ Driemaal antwoordt Petrus dat de Heere het weet. Hij krijgt de opdracht om Zijn lammeren en schapen te weiden en te hoeden. De Heere Jezus zegt ook met welke dood Petrus God zal verheerlijken. En Hij zegt: ‘Volg Mij.’",
  betekenis: "Petrus had driemaal gezegd dat hij de Heere Jezus niet kende (Mattheüs 26:70–74). De Heere Jezus had gezegd: ‘gij, als gij eens zult bekeerd zijn, zo versterk uw broeders’ (Lukas 22:32). Later schrijft Petrus zelf aan de oudsten: ‘Weidt de kudde Gods, die onder u is’ (1 Petrus 5:2).",
  wie: ["Petrus", "Jezus", "Thomas", "Nathanaël"],
  ontdek: { soort: "koppel", titel: "Driemaal gevraagd", paren: [
    ["De eerste keer", "Weid Mijn lammeren"], ["De tweede keer", "Hoed Mijn schapen"], ["De derde keer", "Weid Mijn schapen"], ["Aan het eind", "Volg Mij"]] },
  quiz: [{ q: "Hoeveel discipelen waren er samen aan het meer?", a: ["Zeven", "Twaalf", "Drie"], why: "Johannes 21:2" },
    { q: "Wie zei als eerste: ‘Het is de Heere!’?", a: ["De discipel die Jezus liefhad", "Petrus", "Thomas"], why: "Johannes 21:7" },
    { q: "Wat lag er op het kolenvuur op de oever?", a: ["Vis en brood", "Een lam", "Niets"], why: "Johannes 21:9" },
    { q: "Hoe vaak vroeg de Heere Jezus aan Petrus: hebt gij Mij lief?", a: ["Driemaal", "Eenmaal", "Zevenmaal"], why: "Johannes 21:17" }],
  cross: [["Lukas 5:4–11", "Al eerder ving Petrus op het woord van de Heere Jezus zoveel vis dat het net scheurde; toen zei de Heere: ‘van nu aan zult gij mensen vangen.’"],
    ["Lukas 22:31–32", "De Heere Jezus had voor Petrus gebeden, ‘dat uw geloof niet ophoude’."],
    ["1 Petrus 5:2–4", "Petrus schrijft aan de oudsten: ‘Weidt de kudde Gods.’"]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " Dit was ‘de derde maal’ dat de opgestane Heere Zich aan de discipelen liet zien (Johannes 21:14), binnen de veertig dagen (Handelingen 1:3)." },

{ nr: 133, t: "De hemelvaart", ref: "Handelingen 1:1–14", sectie: "gemeente", stappen: [S("nt-opstanding", 8)], vorm: "plek",
  uitleg: "Lukas begint het boek Handelingen met wat er na de opstanding gebeurde. Veertig dagen lang laat de Heere Jezus Zich levend zien aan de apostelen en spreekt Hij over het Koninkrijk van God. Hij beveelt hun in Jeruzalem te blijven en te wachten op de belofte van de Vader: ze zullen met de Heilige Geest gedoopt worden. Ze vragen of Hij nu het koninkrijk voor Israël zal herstellen. Hij antwoordt dat het hun niet toekomt de tijden te weten die de Vader in Zijn eigen macht heeft. Maar ze zullen kracht ontvangen en Zijn getuigen zijn, in Jeruzalem, Judea, Samaria en tot aan het uiterste van de aarde. Terwijl ze kijken, wordt Hij opgenomen, en een wolk neemt Hem weg uit hun gezicht. Twee mannen in witte kleding zeggen: ‘Gij Galilese mannen, wat staat gij en ziet op naar den hemel?’ Deze Jezus zal op dezelfde manier terugkomen. Dan gaan ze van de Olijfberg terug naar Jeruzalem, naar de opperzaal. Daar blijven ze eensgezind bidden, met de vrouwen, met Maria, de moeder van Jezus, en met Zijn broers.",
  betekenis: "Markus zegt dat de Heere Jezus na Zijn hemelvaart is ‘gezeten aan de rechter hand Gods’ (Markus 16:19). Hij had beloofd: ‘Ik ga heen om u plaats te bereiden’, en: ‘zo kome Ik weder en zal u tot Mij nemen’ (Johannes 14:2–3).",
  wie: ["Jezus", "Petrus", "Maria", "Discipelen"], kw: "hemel",
  ontdek: { soort: "kaart", titel: "Vanaf welke berg?", vraag: "Na de hemelvaart gingen de discipelen terug naar Jeruzalem ‘van den berg, die genaamd wordt de Olijf berg’, een sabbatsreis van de stad (Handelingen 1:12). Wijs de Olijfberg aan.", id: "nt_olijfberg", v: [[31.74, 35.18], [31.81, 35.3]] },
  quiz: [{ q: "Waarop moesten de apostelen in Jeruzalem wachten?", a: ["Op de belofte van de Vader", "Op een brief van de keizer", "Op het volgende paasfeest"], why: "Handelingen 1:4" },
    { q: "Waar zouden de apostelen getuigen van de Heere Jezus zijn?", a: ["In Jeruzalem, Judea, Samaria en tot het uiterste der aarde", "Alleen in Galilea, waar ze vandaan kwamen", "Alleen in de tempel in Jeruzalem"], why: "Handelingen 1:8" },
    { q: "Wat nam de Heere Jezus weg voor de ogen van de apostelen?", a: ["Een wolk", "Een vurige wagen", "Een storm"], why: "Handelingen 1:9" },
    { q: "Wat zeiden de twee mannen in witte kleding?", a: ["Deze Jezus zal zo terugkomen, zoals gij Hem naar de hemel hebt zien gaan", "Gaat terug naar Galilea en wacht daar", "Bouwt hier drie tabernakels"], why: "Handelingen 1:11" },
    { q: "Hoe ver lag de Olijfberg van Jeruzalem?", a: ["Een sabbatsreis", "Drie dagreizen", "Zestig stadiën"], why: "Handelingen 1:12" }],
  cross: [["Lukas 24:50–53", "Bij Bethanië zegende Hij hen en werd opgenomen in de hemel; zij gingen met grote blijdschap terug."],
    ["Johannes 14:2–3", "‘In het huis Mijns Vaders zijn vele woningen.’"],
    ["Markus 16:19", "‘Opgenomen in den hemel, en is gezeten aan de rechter hand Gods.’"],
    ["Efeze 1:20", "God heeft Hem uit de doden opgewekt en ‘gezet tot Zijn rechter hand in den hemel’."]],
  tl: TL, tijd: TIJD, tijdNoot: NOOT + " De hemelvaart was veertig dagen na de opstanding (Handelingen 1:3)." }
  );

  Object.assign(BR.kernwoorden, {
    zachtmoedigheid: { n: "Zachtmoedigheid",
      uitleg: "Zachtmoedig is iemand die niet hard of trots is en niet terugslaat, maar geduldig en vriendelijk blijft, ook als hem onrecht gedaan wordt. De Heere Jezus zegt: ‘leert van Mij, dat Ik zachtmoedig ben en nederig van hart.’ Als Koning kwam Hij Jeruzalem binnen ‘zachtmoedig en gezeten op een ezelin’. De Bijbel noemt zachtmoedigheid een vrucht van de Geest, en de Heere Jezus zegt: ‘Zalig zijn de zachtmoedigen.’",
      refs: [["Mattheüs 11:29", "‘Leert van Mij, dat Ik zachtmoedig ben en nederig van hart; en gij zult rust vinden voor uw zielen.’"],
        ["Mattheüs 21:5", "‘Zie, uw Koning komt tot u, zachtmoedig en gezeten op een ezelin.’"],
        ["Mattheüs 5:5", "‘Zalig zijn de zachtmoedigen; want zij zullen het aardrijk beerven.’"],
        ["Galaten 5:22–23", "Zachtmoedigheid hoort bij de vrucht van de Geest."],
        ["Numeri 12:3", "Ook Mozes wordt ‘zeer zachtmoedig’ genoemd."]] },
    avondmaal: { n: "Avondmaal",
      uitleg: "Het Heilig Avondmaal is de maaltijd die de Heere Jezus instelde in de nacht waarin Hij verraden werd. Hij gaf Zijn discipelen brood en zei: ‘Dat is Mijn lichaam, hetwelk voor u gegeven wordt.’ Hij gaf hun de beker en zei dat die het nieuwe testament in Zijn bloed was. Hij zei: ‘Doet dat tot Mijn gedachtenis.’ Zo dikwijls als de gemeente het avondmaal viert, verkondigt zij de dood van de Heere, ‘totdat Hij komt’.",
      refs: [["Lukas 22:19–20", "De Heere Jezus stelt het avondmaal in."],
        ["1 Korinthe 11:23–26", "Paulus geeft door wat hij van de Heere ontvangen heeft."],
        ["Exodus 12:13–14", "Het pascha: het bloed van het lam als teken, en een feest ter gedachtenis."],
        ["1 Korinthe 5:7", "‘Ons Pascha is voor ons geslacht, namelijk Christus.’"]] },
    waarheid: { n: "Waarheid",
      uitleg: "Waarheid is wat echt zo is, zonder leugen of bedrog. God wordt ‘God der waarheid’ genoemd, en de Heere Jezus zegt: ‘Ik ben de Weg, en de Waarheid, en het Leven.’ Voor Pilatus zegt Hij dat Hij gekomen is om ‘der waarheid getuigenis’ te geven; Pilatus vraagt alleen: ‘Wat is waarheid?’ In Zijn gebed zegt de Heere Jezus tegen de Vader: ‘Uw woord is de waarheid.’ En Hij belooft: ‘de waarheid zal u vrijmaken.’",
      refs: [["Johannes 14:6", "‘Ik ben de Weg, en de Waarheid, en het Leven.’"],
        ["Johannes 18:37–38", "De Heere Jezus voor Pilatus: ‘opdat Ik der waarheid getuigenis geven zou.’"],
        ["Johannes 17:17", "‘Uw woord is de waarheid.’"],
        ["Johannes 8:32", "‘De waarheid zal u vrijmaken.’"],
        ["Psalm 31:6", "‘Gij hebt mij verlost, HEERE, Gij, God der waarheid!’"]] },
    kruis: { n: "Kruis",
      uitleg: "Het kruis was een Romeinse doodstraf voor misdadigers. De Heere Jezus, ‘Die geen zonde gedaan heeft’, werd op Golgotha gekruisigd. De Bijbel zegt dat Hij daar ‘onze zonden in Zijn lichaam gedragen heeft op het hout’. Paulus noemt het woord van het kruis ‘een kracht Gods’ voor wie behouden worden, en hij wil alleen roemen in het kruis van de Heere Jezus Christus. De Heere Jezus zegt ook: wie Hem wil volgen, ‘neme zijn kruis op’.",
      refs: [["1 Petrus 2:22–24", "‘Die Zelf onze zonden in Zijn lichaam gedragen heeft op het hout.’"],
        ["1 Korinthe 1:18", "‘Het woord des kruises ... ons, die behouden worden, is het een kracht Gods.’"],
        ["Galaten 6:14", "Paulus wil alleen roemen ‘in het kruis van onzen Heere Jezus Christus’."],
        ["Mattheüs 16:24", "‘Zo iemand achter Mij wil komen, die verloochene zichzelven, en neme zijn kruis op, en volge Mij.’"]] },
    opstanding: { n: "Opstanding",
      uitleg: "Opstanding betekent dat iemand die gestorven is, weer levend wordt. De Heere Jezus is op de derde dag opgestaan uit de doden: het graf was leeg, en Hij liet Zich levend zien aan veel getuigen. De engel zei: ‘Hij is opgestaan, gelijk Hij gezegd heeft.’ De Heere Jezus zegt: ‘Ik ben de Opstanding en het Leven; die in Mij gelooft zal leven, al ware hij ook gestorven.’ Paulus noemt Hem ‘de Eersteling’ van hen die ontslapen zijn.",
      refs: [["Mattheüs 28:6", "‘Hij is hier niet; want Hij is opgestaan, gelijk Hij gezegd heeft.’"],
        ["1 Korinthe 15:3–8", "Gestorven, begraven, opgewekt ten derden dage, en gezien door veel getuigen."],
        ["Johannes 11:25–26", "‘Ik ben de Opstanding en het Leven.’"],
        ["1 Korinthe 15:20", "‘Christus is opgewekt uit de doden, en is de Eersteling geworden dergenen, die ontslapen zijn.’"]] },
    hemel: { n: "Hemel",
      uitleg: "De hemel is de woonplaats van God; de Heere Jezus leert bidden: ‘Onze Vader, Die in de hemelen zijt’. Na Zijn opstanding is de Heere Jezus opgenomen in de hemel, en daar zit Hij aan de rechterhand van God. Hij zei tegen Zijn discipelen: ‘In het huis Mijns Vaders zijn vele woningen; ... Ik ga heen om u plaats te bereiden.’ De engelen zeiden dat Hij zo zal terugkomen als Hij naar de hemel ging. In de nieuwe hemel en de nieuwe aarde zal God ‘alle tranen van hun ogen afwissen; en de dood zal niet meer zijn’.",
      refs: [["Mattheüs 6:9–10", "‘Onze Vader, Die in de hemelen zijt! ... Uw wil geschiede, gelijk in den hemel alzo ook op de aarde.’"],
        ["Handelingen 1:9–11", "De Heere Jezus wordt opgenomen in de hemel en zal zo terugkomen."],
        ["Johannes 14:2–3", "‘Ik ga heen om u plaats te bereiden.’"],
        ["Markus 16:19", "‘Opgenomen in den hemel, en is gezeten aan de rechter hand Gods.’"],
        ["Openbaring 21:1–4", "De nieuwe hemel en de nieuwe aarde: geen tranen en geen dood meer."]] },
  });
})();
